//B"H
(function(){
  async function getAuthToken() {
    const response = await fetch("https://chatgpt.com/api/auth/session", { credentials:"include", cache:"no-store" });
    const session = await response.json().catch(() => null);
    if (!session?.accessToken) throw new Error("No ChatGPT access token for background automation.");
    return session.accessToken;
  }

  async function getConversation(conversationId, token) {
    const response = await fetch(`https://chatgpt.com/backend-api/conversation/${conversationId}`, {
      credentials:"include", cache:"no-store", headers: { authorization:`Bearer ${token}` }
    });
    if (!response.ok) throw new Error(`Conversation load failed: ${response.status}`);
    return await response.json();
  }

  async function sendChatGptBackground({ conversationId, prompt, onPacket }) {
    const token = await getAuthToken();
    const convo = await getConversation(conversationId, token);
    const response = await fetch("https://chatgpt.com/backend-api/conversation", {
      method:"POST", credentials:"include", cache:"no-store",
      headers:{ "content-type":"application/json", authorization:`Bearer ${token}` },
      body:JSON.stringify(makeBody({ conversationId, prompt, parent: convo?.current_node }))
    });
    if (!response.ok) throw new Error(`ChatGPT send failed: ${response.status}`);
    return await readSse(response, onPacket);
  }

  function makeBody({ conversationId, prompt, parent }) {
    if (!parent) throw new Error("Conversation has no current_node.");
    return { action:"next", conversation_id:conversationId, parent_message_id:parent, model:"auto",
      messages:[{ id:uuid(), author:{ role:"user" }, content:{ content_type:"text", parts:[prompt] }, metadata:{} }] };
  }

  async function readSse(response, onPacket = () => {}) {
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let state = { buffer:"", text:"", messageId:"", conversationId:"", seq:0, doneEmitted:false };
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      state = parseChunk(decoder.decode(value, { stream:true }), state, onPacket);
    }
    if (!state.doneEmitted) onPacket({ phase:"done", seq:state.seq + 1, packet:{ dataNoJSON:"[DONE]" }, text:state.text, conversationId:state.conversationId, messageId:state.messageId });
    return { text:state.text, messageId:state.messageId, conversationId:state.conversationId };
  }

  function parseChunk(chunk, state, onPacket = () => {}) {
    let buffer = state.buffer + chunk;
    const parts = buffer.split(/\r?\n\r?\n/);
    state = { ...state, buffer:parts.pop() || "" };
    for (const block of parts) state = parseBlock(block, state, onPacket);
    return state;
  }

  function parseBlock(block, state, onPacket) {
    const line = block.split(/\r?\n/).find(row => row.startsWith("data:"));
    if (!line) return state;
    const data = line.slice(5).trim();
    if (!data) return state;
    if (data === "[DONE]") {
      const next = { ...state, seq:state.seq + 1, doneEmitted:true };
      onPacket({ phase:"done", seq:next.seq, packet:{ dataNoJSON:"[DONE]" }, text:state.text, conversationId:state.conversationId, messageId:state.messageId });
      return next;
    }
    const parsed = JSON.parse(data);
    const msg = parsed.message || parsed.data?.message;
    const next = { ...state, seq:state.seq + 1, conversationId: parsed.conversation_id || state.conversationId, messageId: msg?.id || state.messageId, text: typeof msg?.content?.parts?.[0] === "string" ? msg.content.parts[0] : state.text };
    onPacket({ phase:"packet", seq:next.seq, packet:parsed, text:next.text, conversationId:next.conversationId, messageId:next.messageId });
    return next;
  }

  function uuid() { return crypto.randomUUID ? crypto.randomUUID() : `BH_${Date.now()}_${Math.random().toString(36).slice(2)}`; }
  globalThis.AwtsmoosBgChatGpt = { sendChatGptBackground, parseChunk };
})();

//B"H
(function(){
  const ALARM = "BH_awtsmoos_background_automation_tick";
  let busy = false;

  async function startAutomation(config = {}) {
    const store = globalThis.AwtsmoosBgAutomationStorage;
    const next = await store.saveAutomationState({
      enabled:true, turns:0, status:"armed", lastError:"", conversationId:config.conversationId,
      graph:config.graph || null, settings:{ ...(config.settings || {}), enabled:true },
      prompt:config.settings?.prompt || config.prompt || "continue"
    });
    announce(next);
    schedule(0.02);
    tickAutomation("start").catch(error => fail(error));
    return store.publicAutomationState(next);
  }

  async function stopAutomation(reason = "stopped") {
    chrome.alarms.clear(ALARM);
    return await savePublic({ enabled:false, status:reason });
  }

  async function statusAutomation() {
    const store = globalThis.AwtsmoosBgAutomationStorage;
    return store.publicAutomationState(await store.loadAutomationState());
  }

  async function tickAutomation(reason = "tick") {
    if (busy) return await statusAutomation();
    const store = globalThis.AwtsmoosBgAutomationStorage;
    const state = await store.loadAutomationState();
    const settings = { ...store.DEFAULTS, ...(state.settings || {}) };
    if (!state.enabled || !state.conversationId) return store.publicAutomationState(state);
    if (Number(state.turns || 0) >= Number(settings.maxTurns || 0)) return await stopAutomation("done:max-turns");
    busy = true;
    try { return await runTurn({ state, settings, reason }); }
    catch (error) { return await fail(error, settings.stopOnError !== false); }
    finally { busy = false; }
  }

  async function runTurn({ state, settings }) {
    const store = globalThis.AwtsmoosBgAutomationStorage;
    const turn = Number(state.turns || 0) + 1;
    const prompt = globalThis.AwtsmoosBgAutomationGraph.chooseAutomationPrompt(state.graph, { ...state, settings, turn }) || state.prompt || settings.prompt;
    await savePublic({ status:`sending:${turn}`, turns:turn, lastPrompt:prompt, visiblePage:false });
    streamMirror({ phase:"start", conversationId:state.conversationId, prompt, turn, seq:0 });
    const result = await globalThis.AwtsmoosBgChatGpt.sendChatGptBackground({
      conversationId:state.conversationId,
      prompt,
      onPacket:event => streamMirror({ ...event, conversationId:event.conversationId || state.conversationId, prompt, turn })
    });
    const next = await store.saveAutomationState({
      status:"waiting", lastReply:result.text || "", lastMessageId:result.messageId || "",
      lastConversationId:result.conversationId || state.conversationId, lastError:""
    });
    announce(next);
    if (turn >= Number(settings.maxTurns || 0)) return await stopAutomation("done:max-turns");
    scheduleNext(Number(settings.delayMs || 1000));
    return store.publicAutomationState(next);
  }

  async function fail(error, stop = true) {
    const next = await globalThis.AwtsmoosBgAutomationStorage.saveAutomationState({ status:"error", lastError:String(error?.stack || error?.message || error) });
    announce(next);
    if (stop) await stopAutomation("error"); else schedule(1);
    console.warn("B'H background automation error", error?.message || error);
    return globalThis.AwtsmoosBgAutomationStorage.publicAutomationState(next);
  }

  async function savePublic(patch) {
    const next = await globalThis.AwtsmoosBgAutomationStorage.saveAutomationState(patch);
    announce(next);
    return globalThis.AwtsmoosBgAutomationStorage.publicAutomationState(next);
  }

  function announce(state) { globalThis.AwtsmoosBgPageDelegate?.broadcastAutomationState?.(globalThis.AwtsmoosBgAutomationStorage.publicAutomationState(state)); }
  function streamMirror(detail) { globalThis.AwtsmoosBgPageDelegate?.broadcastAutomationStream?.(detail); }
  function schedule(delayInMinutes) { chrome.alarms.create(ALARM, { delayInMinutes }); }
  function scheduleNext(delayMs) { const ms = Math.max(100, Number(delayMs || 1000)); schedule(Math.max(0.02, ms / 60000)); setTimeout(() => tickAutomation("timer"), ms); }
  chrome.alarms.onAlarm.addListener(alarm => { if (alarm.name === ALARM) tickAutomation("alarm"); });
  globalThis.AwtsmoosBgAutomationEngine = { startAutomation, stopAutomation, statusAutomation, tickAutomation };
})();

//B"H
(function(){
  function broadcastAutomationState(detail = {}) {
    return broadcast("automation-state", detail);
  }

  function broadcastAutomationStream(detail = {}) {
    return broadcast("automation-stream", detail);
  }

  function broadcast(action, detail = {}) {
    const manager = globalThis.__awtsmoosPortManager;
    const ports = Object.values(manager?.ports || {}).filter(Boolean);
    const message = { action, detail, id:`BH_AUTO_${Date.now()}_${Math.random().toString(36).slice(2)}`, from:"background" };
    let sent = 0;
    for (const port of ports) {
      try { port.postMessage(message); sent++; }
      catch { manager?.onPortDisconnect?.(port); }
    }
    return sent;
  }

  globalThis.AwtsmoosBgPageDelegate = { broadcastAutomationState, broadcastAutomationStream };
})();

